export const FOOTER = "<footer id=\"about\">\n<div class=\"about-grid\">\n<section class=\"about-cell\">\n<h2 class=\"lbl\">Editorial policy</h2>\n<p>Announcements enter as <em>claimed</em>, however confident they sound. Nothing is ever deleted: entries are downgraded and annotated, and the history stays public. Every entry carries a novelty check, including when it comes back clean.</p>\n<p class=\"about-links\"><a href=\"/methodology\">Full rules \u2192</a></p>\n</section>\n<section class=\"about-cell\">\n<h2 class=\"lbl\">Use the data</h2>\n<p>The whole registry is one open file under <a href=\"https://creativecommons.org/licenses/by/4.0/\" target=\"_blank\" rel=\"noopener license\">CC&nbsp;BY&nbsp;4.0</a> and can be reused anywhere with attribution. Take the file if you want everything; the API answers a narrower question, and promises a fixed set of fields the file does not.</p>\n<p class=\"about-links\">\n<a href=\"/data/entries.json\" download>Download JSON</a>\n<a href=\"/api/dataset\">API</a>\n<a href=\"/feed.xml\">RSS</a>\n<a href=\"/feed.json\">JSON Feed</a>\n<a href=\"https://whataifound.org/LICENSE\">License</a>\n</p>\n</section>\n<section class=\"about-cell\">\n<h2 class=\"lbl\">Contribute</h2>\n<p>Most entries have never been checked outside the lab that announced them. A check takes one form to submit, needs no GitHub account, and is credited on the entry and on the contributors page.</p>\n<p class=\"about-links\">\n<a href=\"/contribute\">Contribute \u2192</a>\n<a href=\"/review\">Review queue</a>\n<a href=\"/contributors\">Contributors</a>\n<a href=\"https://github.com/yigitisik/whataifound/blob/main/GOVERNANCE.md\" target=\"_blank\" rel=\"noopener\">Roles</a>\n</p>\n</section>\n<section class=\"about-cell\">\n<h2 class=\"lbl\">Source</h2>\n<p>Site and registry are open on GitHub. Corrections and new entries are welcome by pull request.</p>\n<p class=\"about-links\">\n<a class=\"gh-link\" href=\"https://github.com/yigitisik/whataifound\" target=\"_blank\" rel=\"noopener\"><svg viewBox=\"0 0 16 16\" width=\"18\" height=\"18\" aria-hidden=\"true\"><path fill=\"currentColor\" fill-rule=\"evenodd\" d=\"M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8z\"/></svg>Repository</a>\n<a href=\"/privacy\">Privacy</a>\n<a href=\"mailto:misik6@gatech.edu?subject=whataifound.org%20feedback\" title=\"Submit a finding, suggest a correction, or ask for updates\">Send feedback</a>\n</p>\n</section>\n</div>\n<section class=\"about-note\">\n<h2 class=\"lbl\">Disclaimer</h2>\n<p>We run whataifound.org as an independent editorial project, as volunteer work. Verification and autonomy grades are our good-faith judgments from public information, provided \"as is\" without warranty, and may change as new evidence emerges. Nothing here is scientific, legal, or investment advice. We are not affiliated with, sponsored by, or endorsed by any laboratory or company mentioned; logos and names are trademarks of their owners and appear for identification only. <a href=\"mailto:misik6@gatech.edu\">Get in touch</a></p>\n</section>\n<div class=\"about-foot\">\n<p class=\"cite\">whataifound.org (2026). <em>whataifound.org: A Registry of AI Scientific and Mathematical Discoveries.</em> Retrieved <span id=\"cite-date\">2026</span> from https://whataifound.org/</p>\n<p class=\"colophon\">\u00a9 2026 Isik &amp; Co.</p>\n</div>\n</footer>";
